#include <stdio.h>

void printMessage(const char *msg) {   // const: this function promises not to modify *msg
    printf("%s\n", msg);
}

int main() {
    const int MAX = 100;              // a genuinely constant value
    int *const fixedPtr = NULL;        // pointer itself can't be reassigned (contrived example)

    int arrOfPointers[3];               // NOT the same as a pointer to an array
    int (*pointerToArray)[3];            // this IS a pointer to an array of 3 ints

    printMessage("const correctness demo");
    printf("%d\n", MAX);
    (void)fixedPtr; (void)arrOfPointers; (void)pointerToArray;   // suppress unused warnings
    return 0;
}
